<template>
  <div class="mx-auto max-w-7xl space-y-6 p-4 pb-8">
    <div class="flex flex-col gap-3 md:flex-row md:items-center md:justify-between"><div class="flex items-center gap-3"><Button icon="pi pi-arrow-left" text rounded @click="router.visit('/sales/transactions')" /><div><h1 class="text-xl font-semibold">Transaction Details</h1><p class="text-sm text-slate-500">{{ number }}</p></div></div><div v-if="order" class="flex items-center gap-2"><Button v-if="type==='pos'" label="Receipt" icon="pi pi-print" severity="secondary" outlined @click="openReceipt" /><Tag :value="label(status)" :severity="statusSeverity(status)" /></div></div>
    <div v-if="loading" class="space-y-3"><Skeleton height="8rem" /><Skeleton height="20rem" /></div>
    <template v-else-if="order">
      <div class="grid gap-3 md:grid-cols-4"><div class="summary"><span>Transaction</span><b>{{ number }}</b></div><div class="summary"><span>Channel</span><b>{{ channel }}</b></div><div class="summary"><span>Date</span><b>{{ dateTime(createdAt) }}</b></div><div class="summary"><span>Total</span><b class="text-blue-600">{{ money(total) }}</b></div></div>
      <div class="grid gap-4 lg:grid-cols-3"><Card class="border shadow-sm lg:col-span-2"><template #title>Customer information</template><template #content><div class="grid gap-4 text-sm md:grid-cols-2"><div><p class="meta">Customer</p><p class="font-semibold">{{ customerName }}</p><p class="text-slate-500">{{ customerContact||'No contact details' }}</p></div><div><p class="meta">Branch</p><p class="font-semibold">{{ branchName||'Not assigned' }}</p></div><div v-if="address" class="md:col-span-2"><p class="meta">Delivery address</p><p>{{ address }}</p></div></div></template></Card><Card class="border shadow-sm"><template #title>Payment</template><template #content><div class="space-y-3 text-sm"><div><p class="meta">Status</p><Tag :value="label(paymentStatus)" :severity="paymentSeverity(paymentStatus)" /></div><div><p class="meta">Method</p><p class="font-semibold">{{ label(paymentMethod||'Not specified') }}</p></div><div v-if="paymentReference"><p class="meta">Reference</p><p class="break-all font-mono text-xs">{{ paymentReference }}</p></div></div></template></Card></div>
      <Card class="border shadow-sm"><template #title>Purchased items</template><template #content><div class="overflow-x-auto"><table class="w-full min-w-[760px] text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="p-3 text-left">#</th><th class="p-3 text-left">Product</th><th class="p-3 text-center">Quantity</th><th class="p-3 text-right">Unit price</th><th class="p-3 text-right">Discount</th><th class="p-3 text-right">Line total</th></tr></thead><tbody class="divide-y"><tr v-for="(item,i) in items" :key="item.id||i"><td class="p-3 text-slate-400">{{ i+1 }}</td><td class="p-3"><p class="font-medium">{{ itemName(item) }}</p><p class="text-xs text-slate-500">{{ item.sku||item.product?.sku||'No SKU' }}</p></td><td class="p-3 text-center">{{ item.quantity }}</td><td class="p-3 text-right">{{ money(item.unit_price) }}</td><td class="p-3 text-right">{{ money(item.line_discount||item.discount_amount||0) }}</td><td class="p-3 text-right font-semibold">{{ money(item.line_total||(+item.unit_price*+item.quantity)) }}</td></tr></tbody></table></div></template></Card>
      <div class="grid gap-4 lg:grid-cols-[1fr_22rem]"><Card v-if="notes" class="border shadow-sm"><template #title>Notes</template><template #content><p class="whitespace-pre-line text-sm text-slate-600">{{ notes }}</p></template></Card><Card class="border shadow-sm lg:col-start-2"><template #title>Amount summary</template><template #content><div class="space-y-3 text-sm"><div class="line"><span>Subtotal</span><b>{{ money(subtotal) }}</b></div><div class="line"><span>Discount</span><b>- {{ money(discount) }}</b></div><div class="line"><span>Shipping</span><b>{{ money(shipping) }}</b></div><div class="line"><span>Tax</span><b>{{ money(tax) }}</b></div><div class="line border-t pt-3 text-base"><span class="font-semibold">Total</span><b>{{ money(total) }}</b></div></div></template></Card></div>
    </template>
  </div>
</template>
<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';import { router,usePage } from '@inertiajs/vue3';import { useToast } from 'primevue/usetoast';import salesService from '@/services/sales.service';import { openReceiptPreview } from '@/utils/receiptPreview';import Button from 'primevue/button';import Card from 'primevue/card';import Skeleton from 'primevue/skeleton';import Tag from 'primevue/tag'
const page=usePage(),toast=useToast(),parts=location.pathname.split('/').filter(Boolean),id=Number((page.props as any).params?.id||parts.at(-1)),type=String((page.props as any).params?.type||parts.at(-2));const order=ref<any>(null),loading=ref(true)
const load=async()=>{loading.value=true;try{order.value=type==='ecommerce'?(await salesService.getEcommerceOrder(id)).data:(await salesService.getPosOrder(id)).data}catch(e:any){toast.add({severity:'error',summary:'Unable to load transaction',detail:e.response?.data?.message||'Not found.',life:3000})}finally{loading.value=false}};const number=computed(()=>order.value?.order_number||`${type.toUpperCase()}-${id}`),channel=computed(()=>type==='ecommerce'?'Online':String(order.value?.order_number||'').startsWith('WHO-')?'Wholesale':'In-Store'),status=computed(()=>order.value?.status||'pending'),createdAt=computed(()=>order.value?.placed_at||order.value?.created_at),customerName=computed(()=>order.value?.customer_name||order.value?.shipping_name||'Walk-in customer'),customerContact=computed(()=>order.value?.customer_phone||order.value?.shipping_phone||order.value?.delivery_email),branchName=computed(()=>order.value?.branch?.name||order.value?.assigned_branch?.name),address=computed(()=>order.value?.delivery_address||[order.value?.shipping_address_line,order.value?.shipping_barangay,order.value?.shipping_city,order.value?.shipping_province].filter(Boolean).join(', ')),items=computed(()=>order.value?.items||[]),paymentStatus=computed(()=>order.value?.payment_status||order.value?.payment?.status||'pending'),paymentMethod=computed(()=>order.value?.payment_method||order.value?.payment?.payment_method),paymentReference=computed(()=>order.value?.payment_reference||order.value?.payment?.provider_reference),subtotal=computed(()=>+order.value?.subtotal||0),discount=computed(()=>+order.value?.discount_amount||0),shipping=computed(()=>+(order.value?.shipping_fee??order.value?.delivery_fee)||0),tax=computed(()=>+order.value?.tax_amount||0),total=computed(()=>+order.value?.total_amount||0),notes=computed(()=>order.value?.notes||order.value?.delivery_notes)
const itemName=(x:any)=>x.product_name||x.product?.product_name||x.name||'Product',money=(v:any)=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(+v||0),label=(v:any)=>String(v||'').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase()),dateTime=(v:any)=>v?new Intl.DateTimeFormat('en-PH',{dateStyle:'long',timeStyle:'short'}).format(new Date(v)):'—',paymentSeverity=(v:string)=>v==='paid'?'success':v==='failed'?'danger':v==='refunded'?'info':'warn',statusSeverity=(v:string)=>['completed','delivered'].includes(String(v).toLowerCase())?'success':['cancelled','declined'].includes(String(v).toLowerCase())?'danger':'info'
const openReceipt = async () => {
  try {
    await openReceiptPreview(() => salesService.getPosOrderReceipt(id))
  } catch (error: any) {
    toast.add({ severity: 'error', summary: 'Receipt Unavailable', detail: error?.response?.data?.message || error?.message || 'Unable to prepare the receipt for printing.', life: 3500 })
  }
}
onMounted(load)
</script>
<style scoped>.summary{border:1px solid #e2e8f0;border-radius:.75rem;background:#fff;padding:1rem}.summary span,.meta{display:block;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:#64748b}.summary b{display:block;margin-top:.35rem}.line{display:flex;justify-content:space-between;gap:1rem;color:#64748b}.line b{color:#0f172a}</style>
